#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/mman.h>
#include <linux/kvm.h>
#include <sys/ioctl.h>
#include <stdint.h>

#define KVM_MEM_SIZE (1 << 20)  // 1MB memory
#define PORT_INPUT 0x8000
#define PORT_OUTPUT 0xe9

struct vm_state {
    int kvm_fd;
    int vm_fd;
    int vcpu_fd;
    uint8_t *mem;
};

void init_kvm(struct vm_state *state) {
    state->kvm_fd = open("/dev/kvm", O_RDWR);
    if (state->kvm_fd < 0) {
        perror("Cannot open /dev/kvm");
        exit(1);
    }

    state->vm_fd = ioctl(state->kvm_fd, KVM_CREATE_VM, 0);
    if (state->vm_fd < 0) {
        perror("Cannot create VM");
        exit(1);
    }

    // Allocate and map memory
    state->mem = mmap(NULL, KVM_MEM_SIZE, PROT_READ | PROT_WRITE,
                     MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (state->mem == MAP_FAILED) {
        perror("Cannot mmap memory");
        exit(1);
    }

    struct kvm_userspace_memory_region region = {
        .slot = 0,
        .guest_phys_addr = 0,
        .memory_size = KVM_MEM_SIZE,
        .userspace_addr = (uint64_t)state->mem,
    };

    if (ioctl(state->vm_fd, KVM_SET_USER_MEMORY_REGION, &region) < 0) {
        perror("Cannot set user memory region");
        exit(1);
    }

    // Create VCPU
    state->vcpu_fd = ioctl(state->vm_fd, KVM_CREATE_VCPU, 0);
    if (state->vcpu_fd < 0) {
        perror("Cannot create VCPU");
        exit(1);
    }
}

void load_binary(struct vm_state *state, const char *binary_path) {
    int fd = open(binary_path, O_RDONLY);
    if (fd < 0) {
        perror("Cannot open binary");
        exit(1);
    }

    ssize_t bytes_read = read(fd, state->mem, KVM_MEM_SIZE);
    if (bytes_read < 0) {
        perror("Cannot read binary");
        exit(1);
    }

    close(fd);
}

void run_vm(struct vm_state *state) {
    struct kvm_run *run;
    int run_size = ioctl(state->kvm_fd, KVM_GET_VCPU_MMAP_SIZE, NULL);
    run = mmap(NULL, run_size, PROT_READ | PROT_WRITE, MAP_SHARED, state->vcpu_fd, 0);

    // Initialize registers
    struct kvm_regs regs;
    if (ioctl(state->vcpu_fd, KVM_GET_REGS, &regs) < 0) {
        perror("Cannot get registers");
        exit(1);
    }

    regs.rip = 0;  // Start execution from beginning
    regs.rflags = 0x2;  // Standard flags

    if (ioctl(state->vcpu_fd, KVM_SET_REGS, &regs) < 0) {
        perror("Cannot set registers");
        exit(1);
    }

    // Main execution loop
    while (1) {
        if (ioctl(state->vcpu_fd, KVM_RUN, NULL) < 0) {
            perror("Cannot run VCPU");
            exit(1);
        }

        switch (run->exit_reason) {
            case KVM_EXIT_IO:
                if (run->io.port == PORT_INPUT) {
                    // Handle input port
                    uint8_t input = 0x41;  // Test input 'A'
                    if (run->io.direction == KVM_EXIT_IO_OUT) {
                        printf("Program requesting input at port 0x%x\n", PORT_INPUT);
                        memcpy((void *)run + run->io.data_offset, &input, 1);
                    }
                } else if (run->io.port == PORT_OUTPUT) {
                    // Handle output port
                    uint8_t output;
                    memcpy(&output, (void *)run + run->io.data_offset, 1);
                    printf("Output at port 0x%x: 0x%02x ('%c')\n", PORT_OUTPUT, output, output);
                }
                break;
            case KVM_EXIT_HLT:
                printf("VM halted\n");
                return;
            default:
                printf("Unexpected exit reason: %d\n", run->exit_reason);
                return;
        }
    }

    munmap(run, run_size);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <binary>\n", argv[0]);
        return 1;
    }

    struct vm_state state;
    init_kvm(&state);
    load_binary(&state, argv[1]);
    run_vm(&state);

    // Cleanup
    munmap(state.mem, KVM_MEM_SIZE);
    close(state.vcpu_fd);
    close(state.vm_fd);
    close(state.kvm_fd);

    return 0;
}

