    struct kvm_userspace_memory_region region = {
        .slot = 0,
        .flags = 0,
        .guest_phys_addr = 0,
        .memory_size = mem_size,
        .userspace_addr = (uint64_t)mem,
    };

    if (ioctl(vm_fd, KVM_SET_USER_MEMORY_REGION, &region) < 0) {
        perror("Cannot set user memory region");
        exit(1);
    }

    return mem;
}

void send_input(int vcpu_fd, uint16_t port, uint8_t value) {
    struct kvm_run *run;
    size_t mmap_size;

    mmap_size = ioctl(vcpu_fd, KVM_GET_VCPU_MMAP_SIZE, NULL);
    run = mmap(NULL, mmap_size, PROT_READ | PROT_WRITE, MAP_SHARED, vcpu_fd, 0);

    // Setup I/O port write
    struct kvm_regs regs;
    if (ioctl(vcpu_fd, KVM_GET_REGS, &regs) < 0) {
        perror("KVM_GET_REGS");
        exit(1);
    }

    // Set registers for port I/O
    regs.rax = value;
    regs.rdx = port;

    if (ioctl(vcpu_fd, KVM_SET_REGS, &regs) < 0) {
        perror("KVM_SET_REGS");
        exit(1);
    }

    // Run the VM
    if (ioctl(vcpu_fd, KVM_RUN, NULL) < 0) {
        perror("KVM_RUN");
        exit(1);
    }

    // Check response
    if (run->exit_reason == KVM_EXIT_IO) {
        if (run->io.direction == KVM_EXIT_IO_OUT && run->io.port == KVM_IO_PORT_0xe9) {
            printf("Output on port 0xe9: 0x%x\n", *(uint8_t *)((char *)run + run->io.data_offset));
        }
    }

    munmap(run, mmap_size);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <challenge_binary>\n", argv[0]);
        return 1;
    }

    int kvm_fd, vm_fd, vcpu_fd;
    setup_kvm(&kvm_fd, &vm_fd, &vcpu_fd);
    void *mem = setup_memory(vm_fd, RAM_SIZE);

    // Load challenge binary
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("Cannot open challenge binary");
        return 1;
    }
    fread(mem, 1, RAM_SIZE, f);
    fclose(f);

    printf("Starting KVM test...\n");

    // Test sequence
    uint8_t test_sequence[] = {0x41, 0x42, 0x43, 0x44}; // Test with "ABCD"
    for (int i = 0; i < sizeof(test_sequence); i++) {
        printf("Sending input: 0x%02x\n", test_sequence[i]);
        send_input(vcpu_fd, KVM_IO_PORT_0x8000, test_sequence[i]);
        usleep(100000); // Small delay between inputs
    }

    // Cleanup
    munmap(mem, RAM_SIZE);
    close(vcpu_fd);
    close(vm_fd);
    close(kvm_fd);

    return 0;
}

