#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

#define KVM_MEM_SIZE 0x200000
#define IO_PORT_IN 0x8000
#define IO_PORT_OUT 0xe9

void setup_kvm(int *kvm_fd, int *vm_fd, void **mem) {
    // Open KVM device
    *kvm_fd = open("/dev/kvm", O_RDWR);
    if (*kvm_fd < 0) {
        perror("open /dev/kvm");
        exit(1);
    }

    // Create VM
    *vm_fd = ioctl(*kvm_fd, KVM_CREATE_VM, 0);
    if (*vm_fd < 0) {
        perror("KVM_CREATE_VM");
        exit(1);
    }

    // Allocate memory
    *mem = mmap(NULL, KVM_MEM_SIZE, PROT_READ | PROT_WRITE, 
                MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (*mem == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    // Map memory to VM
    struct kvm_userspace_memory_region region = {
        .slot = 0,
        .flags = 0,
        .guest_phys_addr = 0,
        .memory_size = KVM_MEM_SIZE,
        .userspace_addr = (unsigned long)*mem,
    };

    if (ioctl(*vm_fd, KVM_SET_USER_MEMORY_REGION, &region) < 0) {
        perror("KVM_SET_USER_MEMORY_REGION");
        exit(1);
    }
}

void load_binary(void *mem, const char *binary_path) {
    FILE *f = fopen(binary_path, "rb");
    if (!f) {
        perror("fopen binary");
        exit(1);
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fread(mem, 1, size, f) != size) {
        perror("fread binary");
        exit(1);
    }

    fclose(f);
}

void test_io(int vcpu_fd, struct kvm_run *run) {
    // Test sequence
    char test_input[] = "TEST";
    int test_len = strlen(test_input);
    int i;

    for (i = 0; i < test_len; i++) {
        // Send input through port 0x8000
        printf("Sending byte: 0x%02x\n", test_input[i]);

        // Read response from port 0xe9
        if (run->io.direction == KVM_EXIT_IO_OUT && run->io.port == IO_PORT_OUT) {
            char *data = (char *)run + run->io.data_offset;
            printf("Response: 0x%02x\n", *data);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <binary_path>\n", argv[0]);
        return 1;
    }

    int kvm_fd, vm_fd, vcpu_fd;
    void *mem;
    struct kvm_run *run;

    // Setup KVM environment
    setup_kvm(&kvm_fd, &vm_fd, &mem);

    // Load challenge binary
    load_binary(mem, argv[1]);

    // Create VCPU
    vcpu_fd = ioctl(vm_fd, KVM_CREATE_VCPU, 0);
    if (vcpu_fd < 0) {
        perror("KVM_CREATE_VCPU");
        exit(1);
    }

    // Get size of mmap for vcpu
    int mmap_size = ioctl(kvm_fd, KVM_GET_VCPU_MMAP_SIZE, NULL);
    if (mmap_size <= 0) {
        perror("KVM_GET_VCPU_MMAP_SIZE");
        exit(1);
    }

    // Map VCPU memory
    run = mmap(NULL, mmap_size, PROT_READ | PROT_WRITE, MAP_SHARED, vcpu_fd, 0);
    if (run == MAP_FAILED) {
        perror("mmap vcpu");
        exit(1);
    }

    // Test I/O operations
    test_io(vcpu_fd, run);

    // Cleanup
    munmap(run, mmap_size);
    munmap(mem, KVM_MEM_SIZE);
    close(vcpu_fd);
    close(vm_fd);
    close(kvm_fd);

    return 0;
}

