from pwn import *

def extract_payload():
    # Load the binary
    elf = ELF('/home/ctfplayer/ctf_files/kvm/challenge')

    # Find and extract the .payload section
    try:
        payload_section = elf.get_section_by_name('.payload')
        if payload_section:
            return payload_section.data()
    except:
        # If .payload doesn't exist, try to find any unusual sections
        for section in elf.sections:
            if section.name.startswith('.pay') or 'data' in section.name.lower():
                return section.data()
    return None

def reverse_xor(data):
    # Reverse the XOR transformation (input = expected_output ^ 0xff)
    return bytes([b ^ 0xff for b in data])

def main():
    # Extract the payload
    payload_data = extract_payload()
    if payload_data:
        print("Extracted payload data:")
        print(hexdump(payload_data))

        # Calculate input sequence
        input_sequence = reverse_xor(payload_data)
        print("\nCalculated input sequence:")
        print(hexdump(input_sequence))

        # Test the input against the challenge
        p = process('/home/ctfplayer/ctf_files/kvm/challenge')
        p.send(input_sequence)
        try:
            response = p.recvall(timeout=2)
            print("\nProgram output:")
            print(response.decode('latin-1'))
        except:
            print("\nNo more output from program")
        p.close()

if __name__ == '__main__':
    main()

